?>
<section class="erp-card"><h2>هزینه و درآمد متفرقه</h2><?php FinanceController::exportLink($cid,'expenses'); ?><form method="get" class="erp-filter erp-no-print"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="expenses"><label>نوع<select name="kind"><option value="">همه</option><option value="expense" <?php selected(Request::str('get','kind'),'expense'); ?>>هزینه</option><option value="income" <?php selected(Request::str('get','kind'),'income'); ?>>درآمد</option></select></label><?php foreach(['from'=>'از تاریخ شمسی','to'=>'تا تاریخ شمسی'] as $key=>$label): ?><label><?php echo esc_html($label); ?><input name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr(Request::str('get',$key,10)); ?>" data-jalali></label><?php endforeach; ?>
<?php foreach(['category_id'=>['expense_categories','سرفصل'],'party_id'=>['parties','شخص'],'project_id'=>['cost_dimensions','پروژه'],'branch_id'=>['cost_dimensions','شعبه'],'center_id'=>['cost_dimensions','مرکز هزینه']] as $key=>$meta): ?><label><?php echo esc_html($meta[1]); ?><select name="<?php echo esc_attr($key); ?>"><option value="0">همه</option><?php $kind=substr($key,0,-3);$rows=Db::rows('SELECT id,name FROM '.Db::t($meta[0]).' WHERE company_id=%d'.($meta[0]==='cost_dimensions'?' AND kind=%s':'').' ORDER BY name',...($meta[0]==='cost_dimensions'?[$cid,$kind]:[$cid]));foreach($rows as $r): ?><option value="<?php echo (int)$r['id']; ?>" <?php selected(Request::int('get',$key),$r['id']); ?>><?php echo esc_html($r['name']); ?></option><?php endforeach; ?></select></label><?php endforeach; ?><label>وضعیت<select name="status"><?php foreach(['issued'=>'صادرشده','void'=>'باطل',''=>'همه'] as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected(Request::str('get','status',10,'issued'),$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button class="btn btn-outline" type="submit">اعمال فیلتر</button></form>
<p>جمع هزینه: <?php echo esc_html(Money::fmt((int)$data['total']['expenses'],Ctx::unit())); ?> | جمع درآمد: <?php echo esc_html(Money::fmt((int)$data['total']['income'],Ctx::unit())); ?></p><div class="erp-scroll"><table class="erp-table"><thead><tr><th>شماره</th><th>تاریخ</th><th>نوع / سرفصل</th><th>شخص</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody><?php foreach($data['rows'] as $r): ?><tr><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'expense_view','id'=>$r['id']])); ?>"><?php echo esc_html(Money::toFa($r['number'])); ?></a></td><td><?php echo esc_html(Jalali::format($r['doc_date'])); ?></td><td><?php echo esc_html(($r['kind']==='expense'?'هزینه':'درآمد').' / '.$r['category_name']); ?></td><td><?php echo esc_html($r['party_name']); ?></td><td><?php echo esc_html(Money::fmt((int)$r['amount'],Ctx::unit())); ?></td><td><?php echo $r['status']==='issued'?'صادرشده':'باطل'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($data['pages'],$data['page']); ?></section>
<?php if(Ctx::can('expense.create')): ?><section class="erp-card"><h3>ثبت هزینه یا درآمد</h3><form method="post" class="erp-form"><?php self::form('module_expense_issue',$cid,'expenses');$options=[0=>'انتخاب سرفصل'];foreach(Db::rows('SELECT id,name,kind FROM '.Db::t('expense_categories').' WHERE company_id=%d AND is_active=1 ORDER BY code',$cid) as $r)$options[$r['id']]=($r['kind']==='expense'?'هزینه: ':'درآمد: ').$r['name'];self::select('category_id','سرفصل',$options);$parties=[0=>'انتخاب شخص'];foreach(Db::rows('SELECT id,name FROM '.Db::t('parties').' WHERE company_id=%d AND is_active=1 ORDER BY name',$cid) as $r)$parties[$r['id']]=$r['name'];self::select('party_id','شخص',$parties);self::input('doc_date','تاریخ شمسی',Jalali::format(\Agah\Erp\Core\FiscalContext::today($cid),false),'text','required data-jalali');self::input('due_date','سررسید شمسی',Jalali::format(\Agah\Erp\Core\FiscalContext::today($cid),false),'text','required data-jalali');self::input('amount','مبلغ','','text','required inputmode="decimal"');self::input('description','شرح');foreach(['project'=>'پروژه','branch'=>'شعبه','center'=>'مرکز هزینه'] as $kind=>$label){$options=[0=>'بدون تخصیص'];foreach(Db::rows('SELECT id,name FROM '.Db::t('cost_dimensions').' WHERE company_id=%d AND kind=%s AND is_active=1 ORDER BY code',$cid,$kind) as $r)$options[$r['id']]=$r['name'];self::select($kind.'_id',$label,$options);}if(Ctx::can('expense.edit'))require __DIR__.'/finance-payment-fields.php'; ?><button class="btn btn-primary" type="submit">صدور و ثبت سند</button></form><p>مبلغ تسویه خالی باشد، برگه پرداخت‌نشده/دریافت‌نشده ثبت می‌شود. تصویر رسید را پس از ثبت برگه اضافه کنید.</p></section><?php endif; ?>
